"""Mirrors botocore.session get_* helpers that must not match AWS-op heuristic."""


class ComponentLocator:
    def __init__(self):
        self._components = {}

    def get_component(self, name):
        return self._components.get(name)


class Session:
    def __init__(self, env_vars=None):
        self._internal_components = ComponentLocator()

    def get_component(self, name):
        return self._internal_components.get_component(name)

    def _get_internal_component(self, name):
        return self._internal_components.get_component(name)

    def get_available_regions(
        self, service_name, partition_name="aws", allow_non_regional=False
    ):
        _ = self._get_internal_component("endpoint_resolver")
        return []

    def get_service_model(self, service_name, api_version=None):
        class Model:
            operation_names = []

        return Model()


def get_session(env_vars=None):
    return Session(env_vars)
